#include "cli.hpp"

namespace andes_sim {
namespace {

// Try to read an option's value at args[i]. Supports both `--flag value`
// (consumes the next token, advancing i) and `--flag=value`.
//   returns  1 = matched, `out` set
//            0 = this token is not `flag`
//           -1 = matched `--flag` but no value follows
int match_opt(const std::vector<std::string>& args, size_t& i,
              const std::string& flag, std::string& out) {
  const std::string& a = args[i];
  if (a == flag) {
    if (i + 1 >= args.size()) return -1;
    out = args[++i];
    return 1;
  }
  const std::string pfx = flag + "=";
  if (a.starts_with(pfx)) {
    out = a.substr(pfx.size());
    return 1;
  }
  return 0;
}

}  // namespace

Cli parse_cli(const std::vector<std::string>& args) {
  Cli c;
  if (args.empty()) return c;  // no subcommand; caller prints usage

  // First token is the subcommand, unless it is a top-level help request.
  if (args[0] == "-h" || args[0] == "--help") {
    c.help = true;
    return c;
  }
  c.subcommand = args[0];

  for (size_t i = 1; i < args.size(); ++i) {
    const std::string& a = args[i];

    if (a == "--") {  // the passthrough boundary: rest is verbatim
      c.has_passthrough = true;
      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
      break;
    }
    if (a == "-h" || a == "--help") {
      c.help = true;
      continue;
    }
    if (a == "--dry-run") {
      c.dry_run = true;
      continue;
    }

    const struct {
      const char* flag;
      std::string* out;
    } opts[] = {{"--model", &c.model},
                {"--engine", &c.engine},
                {"--trigger", &c.trigger},
                {"--what", &c.what}};
    bool consumed = false;
    for (const auto& o : opts) {
      int r = match_opt(args, i, o.flag, *o.out);
      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
      if (r > 0) { consumed = true; break; }
    }
    if (consumed) continue;

    if (a.size() > 1 && a[0] == '-') {
      c.error = "unknown option: " + a;
      return c;
    }
    c.positional.push_back(a);
  }

  return c;
}

Cli parse_cli(int argc, char** argv) {
  std::vector<std::string> args;
  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
  return parse_cli(args);
}

}  // namespace andes_sim

// Subprocess helpers for andes-sim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/accurate.
#ifndef ANDES_SIM_PROCESS_HPP
#define ANDES_SIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --model fast|accurate`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_PROCESS_HPP

