93	    if (p.ok) {
94	      EngineDescriptor sd;
95	      std::string err = descriptor_from_json(p.value, sd);
96	      if (err.empty()) {
97	        sd.bin_path = bin.string();
98	        sd.source = "sidecar";
99	        d = std::move(sd);
100	        return true;
101	      }
102	      warn = sidecar.string() + ": invalid descriptor: " + err;
103	    } else {
