112	// `prefix` filters candidate basenames; empty accepts any executable. The
113	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
114	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
115	// lives in the call site, not in this engine-agnostic scanner.
116	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
117	              std::set<std::string>& seen) {
118	  std::error_code ec;
119	  if (!fs::is_directory(dir, ec)) return;
120	
121	  std::vector<fs::path> entries;
122	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
123	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
124	
125	  for (const fs::path& p : entries) {
126	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
127	    if (!is_executable_file(p)) continue;
128	    EngineDescriptor d;
129	    std::string warn;
130	    if (describe_one(p, d, warn)) {
131	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
132	    } else if (!warn.empty()) {
133	      out.warnings.push_back(warn);
134	    }
135	  }
136	}
