    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
  std::vector<EngineDescriptor> engines = {
      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
      fake("verilator:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
  };
  Plan plan;
  plan.elf = "/e";
  plan.mem_size = 134217728;
  plan.steps = {
      {"qemu", "fast-leg", {"csr", {}}},
      {"verilator:test", "accurate-leg", {"csr", {}}},
  };
  RuntimeCtx rc;
  rc.mmap_path = "/mm";
  rc.mem_size = 134217728;
  rc.mmap_base = "0x0";
  rc.plugin_path = "/pl";

  {
    std::string err;
    std::vector<std::vector<std::string>> argvs =
        plan_argvs(plan, engines, "/wd", rc, err);
    CHECK(err.empty());
    CHECK(argvs.size() == 2);
    if (argvs.size() == 2) {
      // step 0 (qemu): drains to state-0.bin; no state_in referenced
      check_eq(argvs[0],
               {"/qbin", "-object",
                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
                "enable=on,target=native", "-bios", "/e", "-plugin",
                "/pl,outfile=/wd/state-0.bin"},
               "step0");
      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
      check_eq(argvs[1],
               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
               "step1");
    }
  }
  // unknown engine id is an error
  {
    Plan bad = plan;
    bad.steps[0].engine_id = "nope";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }
  // a role the engine has no template for is an error
  {
    Plan bad = plan;
    bad.steps[1].role = "no-such-role";
    std::string err;
    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
    CHECK(!err.empty());
  }

  return andes_sim::test::report("plan");
}

// Tiny assert-and-count harness shared by the driver's standalone unit tests
// (cli_test, json_test, and F5+ infra tests). No doctest dependency: each test
// is its own executable, calls CHECK(...) for each assertion, and ends with
// `return andes_sim::test::report("<name>");`.
#ifndef ANDES_SIM_TEST_CHECK_HPP
#define ANDES_SIM_TEST_CHECK_HPP

#include <cstdio>

namespace andes_sim::test {

inline int g_failures = 0;

inline int report(const char* what) {
  if (g_failures) {
    std::fprintf(stderr, "%d check(s) failed\n", g_failures);
    return 1;
  }
  std::printf("all %s checks passed\n", what);
  return 0;
}

}  // namespace andes_sim::test

#define CHECK(cond)                                                        \
  do {                                                                     \
    if (!(cond)) {                                                         \
      std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
      ++andes_sim::test::g_failures;                                       \
    }                                                                      \
  } while (0)

#endif  // ANDES_SIM_TEST_CHECK_HPP

