// Small text helpers shared across the command renderers (list, doctor).
// Header-only; no dependencies beyond the standard library.
#ifndef ANDES_SIM_STRUTIL_HPP
#define ANDES_SIM_STRUTIL_HPP

#include <string>
#include <vector>

namespace andes_sim {

// Left-justify `s` to width `w` (pad with spaces; never truncate).
inline std::string ljust(std::string s, size_t w) {
  if (s.size() < w) s.append(w - s.size(), ' ');
  return s;
}

// Join `v` with `sep` between elements.
inline std::string join(const std::vector<std::string>& v, const char* sep = ",") {
  std::string s;
  for (size_t k = 0; k < v.size(); ++k) {
    if (k) s += sep;
    s += v[k];
  }
  return s;
}

// Engine VLEN for display: a positive width prints as its number, 0/absent "-".
inline std::string vlen_str(long v) {
  return v > 0 ? std::to_string(v) : std::string("-");
}

}  // namespace andes_sim

#endif  // ANDES_SIM_STRUTIL_HPP

// Placeholder substitution for engine invoke templates -- the template-driven
// port of orchestrator/spawn.py (minus QEMU2). spawn.py hand-built each argv in
// Python; here the argv *shape* lives in each engine's `invoke` template (from
// `--describe`, see docs/engine_interface.md) and build_argv fills the
// {placeholders} from a context map. The framework thus keeps zero per-engine
// argv code: a new engine ships its own template.
#ifndef ANDES_SIM_ARGV_HPP
#define ANDES_SIM_ARGV_HPP

#include <map>
#include <string>
#include <vector>

namespace andes_sim {

// Substitute every "{key}" in `tmpl`'s args with `ctx.at(key)`. A key may
// appear anywhere in an arg (so "mem-path={mmap},size={mmap_size}" expands in
// one arg) and more than once. Recognised keys come from `ctx`; a "{key}" with
// no matching ctx entry is an error (returns {} and sets `err`). On success
// `err` is cleared and the fully-resolved argv is returned.
std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
                                    const std::map<std::string, std::string>& ctx,
                                    std::string& err);

}  // namespace andes_sim

#endif  // ANDES_SIM_ARGV_HPP

/* Tier-2 C-level handoff smoke test (2-phase: QEMU1 -> vsim).
 *
 * Phase 1 (QEMU1): printf via newlib stdio -> libgloss_vh -> semihosting,
 *   handled by QEMU. Then csrwi 0x7C0, 0 -- plugin drains state.
 * Phase 2 (vsim):  empty body. Phase-2 rule (rt_c_helpers.h): no syscall
 *   may issue inside this span. vsim drains at csrwi 0x7C0, 1 and exits 200.
 *
 * (The old phase-3 QEMU2 printf was removed with the QEMU2 leg.)
 */

#include "runtime/rt_c_helpers.h"
#include <stdio.h>

int main(void)
{
  printf("hello from QEMU1\n");
  fflush(stdout);

  enter_vsim();
  /* Phase 2: vsim. No syscalls. */
  exit_vsim();

  return 0;
}

